update par_items set enabled=0 where id in ('bb_devil','bb_god','bb_royal','bb_void','ti_chosen','ti_demon','ti_royal','ti_walker','ti_builder','bb_blox','ti_petal','bb_sakura','ti_frost','bb_frost');
