update par_owned set item_id='bundle:bn_sakura:legacy' where item_id='bundle:bn_sakura:main';
update par_owned set item_id='bundle:bn_frost:legacy' where item_id='bundle:bn_frost:main';
update par_items set descr='A brick-built set. Legacy is the classic frame, nameplate and badge. Modern adds the Master Builder title and brick message style.',data='{"variants":{"legacy":{"label":"Legacy","items":["fr_blox","np_blox","bd_blocks"],"vanity_days":0,"price":36,"gift_price":33,"server_price":0},"modern":{"label":"Modern","items":["fr_blox","np_blox","bd_blocks","ti_builder","bb_blox"],"vanity_days":0,"price":66,"gift_price":59,"server_price":0}}}' where id='bn_blox';
update par_items set descr='Soft and pink. Legacy is the classic nameplate, frame, hearts effect and name. Modern adds the heart badge, Petal Dancer title and blossom message style.',data='{"variants":{"legacy":{"label":"Legacy","items":["np_sakura","fr_rose","ef_hearts","nf_sakura"],"vanity_days":0,"price":42,"gift_price":38,"server_price":0},"modern":{"label":"Modern","items":["np_sakura","fr_rose","ef_hearts","nf_sakura","bd_heart","ti_petal","bb_sakura"],"vanity_days":0,"price":74,"gift_price":67,"server_price":0}}}' where id='bn_sakura';
update par_items set descr='Cold and sharp. Legacy is the classic nameplate, frame, snowfall and name. Modern adds the gem badge, Frostborn title and frost message style.',data='{"variants":{"legacy":{"label":"Legacy","items":["np_glacier","fr_ice","ef_snow","nf_ice"],"vanity_days":0,"price":42,"gift_price":38,"server_price":0},"modern":{"label":"Modern","items":["np_glacier","fr_ice","ef_snow","nf_ice","bd_gem","ti_frost","bb_frost"],"vanity_days":0,"price":72,"gift_price":65,"server_price":0}}}' where id='bn_frost';
